} State;

int solve() {
    memset(visited, 0, sizeof(visited));
    State q[MAX_H * MAX_W * MAX_LEN];
    int front = 0, rear = 0;

    // Initial state
    int gx = girl_start.x, gy = girl_start.y;
    int t = 0;
    int state_idx = 0;
    visited[gy][gx][state_idx] = 1;
    q[rear].x = gx; q[rear].y = gy; q[rear].time = 0; rear++;

    // Precompute ghost positions for each time modulo cmd_len
    Point ghost_pos[MAX_LEN];
    int ghx = ghost_start.x, ghy = ghost_start.y;
    ghost_pos[0].x = ghx; ghost_pos[0].y = ghy;
    for (int i = 0; i < cmd_len; i++) {
        char cmd = commands[i];
        int nx = ghx, ny = ghy;
        if (cmd == 'N') ny--;
        else if (cmd == 'S') ny++;
        else if (cmd == 'E') nx++;
        else if (cmd == 'W') nx--;
        // Ghost can go through walls, but we need to keep within grid? 
        // Problem says ghost can pass through walls, so no bounds check needed? 
        // Actually ghost movement pattern is given; it may go out of bounds? 
        // We'll assume ghost stays within grid? The pattern might move it out; 
        // but since ghost can pass through walls, it can go anywhere, but we still track position.
        // For simplicity, we allow ghost to go out of bounds; but then meeting can't happen if girl can't go there.
        // We'll just track ghost position without bounds.
        ghx = nx; ghy = ny;
        ghost_pos[(i+1) % cmd_len].x = ghx;
        ghost_pos[(i+1) % cmd_len].y = ghy;
    }

    // BFS
    while (front < rear) {
        State cur = q[front++];
        int cx = cur.x, cy = cur.y, ct = cur.time;

        // Check if meeting at current time (already checked initial, but for others)
        int ghost_idx = ct % cmd_len;
        int gx_ghost = ghost_pos[ghost_idx].x;
        int gy_ghost = ghost_pos[ghost_idx].y;
        if (cx == gx_ghost && cy == gy_ghost) {
            printf("%d %d %d\n", ct, cy, cx);
            return 1;
        }

        // Try 5 moves
        for (int d = 0; d < 5; d++) {
            int nx = cx + dx[d];
            int ny = cy + dy[d];
            int nt = ct + 1;

            // Check bounds and if cell is open for girl
            if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
            if (grid[ny][nx] != '.') continue;

            int nidx = nt % cmd_len;
            if (visited[ny][nx][nidx]) continue;

            // Check if ghost is at this position at this time? 
            // Actually we need to meet exactly, so we can check when we pop, but to avoid unnecessary states,
            // we can check if ghost is there at time nt; if so, we can output directly.
            int gx_next = ghost_pos[nidx].x;
            int gy_next = ghost_pos[nidx].y;
            if (nx == gx_next && ny == gy_next) {
                printf("%d %d %d\n", nt, ny, nx);
                return 1;
            }

            visited[ny][nx][nidx] = 1;
            q[rear].x = nx; q[rear].y = ny; q[rear].time = nt; rear++;
        }
    }
    return 0;
}

