int main(void) {
    int W, H;
    const int dx[5] = {0, 0, -1, 1, 0};   /* N, S, W, E, stay */
    const int dy[5] = {-1, 1, 0, 0, 0};

    while (scanf("%d %d", &W, &H) == 2) {
        if (W == 0 && H == 0) break;

        char **grid = (char **)malloc(H * sizeof(char *));
        for (int i = 0; i < H; i++) {
            grid[i] = (char *)malloc((W + 1) * sizeof(char));
            scanf("%s", grid[i]);
        }

        int gx0, gy0;
        scanf("%d %d", &gx0, &gy0);
        gx0--; gy0--;

        char pattern[10005];
        scanf("%s", pattern);
        int L = (int)strlen(pattern);

        /* Ghost positions for times 0..L */
        int *gpx = (int *)malloc((L + 1) * sizeof(int));
        int *gpy = (int *)malloc((L + 1) * sizeof(int));
        gpx[0] = gx0;
        gpy[0] = gy0;

        for (int t = 0; t < L; t++) {
            int x = gpx[t], y = gpy[t];
            char c = pattern[t];
            if (c == 'N') y--;
            else if (c == 'S') y++;
            else if (c == 'W') x--;
            else if (c == 'E') x++;
            gpx[t + 1] = x;
            gpy[t + 1] = y;
        }

        int total = W * H;
        char *cur = (char *)calloc(total, sizeof(char));
        char *nxt = (char *)calloc(total, sizeof(char));

        /* Girl can start at any '.' cell at time 0 */
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                if (grid[y][x] == '.') cur[y * W + x] = 1;
            }
        }

        int found = 0;
        int ans_t = -1, ans_x = -1, ans_y = -1;

        /* Check time 0 */
        if (0 <= gpx[0] && gpx[0] < W && 0 <= gpy[0] && gpy[0] < H &&
            grid[gpy[0]][gpx[0]] == '.' && cur[gpy[0] * W + gpx[0]]) {
            found = 1;
            ans_t = 0;
            ans_x = gpx[0];
            ans_y = gpy[0];
        }

        for (int t = 0; t < L && !found; t++) {
            memset(nxt, 0, total);

            for (int y = 0; y < H; y++) {
                for (int x = 0; x < W; x++) {
                    if (!cur[y * W + x]) continue;
                    for (int k = 0; k < 5; k++) {
                        int nx = x + dx[k];
                        int ny = y + dy[k];
                        if (0 <= nx && nx < W && 0 <= ny && ny < H &&
                            grid[ny][nx] == '.') {
                            nxt[ny * W + nx] = 1;
                        }
                    }
                }
            }

            int gx = gpx[t + 1], gy = gpy[t + 1];
            if (0 <= gx && gx < W && 0 <= gy && gy < H &&
                grid[gy][gx] == '.' && nxt[gy * W + gx]) {
                found = 1;
                ans_t = t + 1;
                ans_x = gx;
                ans_y = gy;
                break;
            }

            char *tmp = cur;
            cur = nxt;
            nxt = tmp;
        }

        if (found) {
            printf("%d %d %d\n", ans_t, ans_x + 1, ans_y + 1);
        } else {
            printf("impossible\n");
        }

        free(cur);
        free(nxt);
        free(gpx);
        free(gpy);
        for (int i = 0; i < H; i++) free(grid[i]);
        free(grid);
    }

    return 0;
}

