public class GhostEncounter {
    static final int[] dx = {-1, 1, 0, 0, 0};
    static final int[] dy = {0, 0, -1, 1, 0};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNext()) {
            int h = sc.nextInt();
            int w = sc.nextInt();
            if (h == 0 && w == 0) break;

            char[][] grid = new char[h][w];
            int startX = -1, startY = -1;

            for (int i = 0; i < h; i++) {
                String line = sc.next();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'G') {
                        startX = i;
                        startY = j;
                        grid[i][j] = '.';
                    }
                }
            }

            String pattern = sc.next();
            int len = pattern.length();

            int[][][] ghostPos = new int[len + 1][h][w];
            for (int[][] layer : ghostPos) {
                for (int[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }

            // BFS for ghost positions over time modulo pattern length
            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{startX, startY, 0});
            ghostPos[0][startX][startY] = 0;

            int[] gdx = {-1, 1, 0, 0};
            int[] gdy = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                int x = cur[0], y = cur[1], t = cur[2];
                int nt = (t + 1) % (len + 1);
                if (t < len) {
                    char cmd = pattern.charAt(t);
                    int nx = x, ny = y;
                    if (cmd == 'N') nx--;
                    else if (cmd == 'S') nx++;
                    else if (cmd == 'W') ny--;
                    else if (cmd == 'E') ny++;

                    if (nx >= 0 && nx < h && ny >= 0 && ny < w && grid[nx][ny] != '#') {
                        if (ghostPos[nt][nx][ny] == -1) {
                            ghostPos[nt][nx][ny] = t + 1;
                            queue.add(new int[]{nx, ny, t + 1});
                        }
                    } else {
                        if (ghostPos[nt][x][y] == -1) {
                            ghostPos[nt][x][y] = t + 1;
                            queue.add(new int[]{x, y, t + 1});
                        }
                    }
                } else {
                    // after pattern ends, ghost stays
                    int nx = x, ny = y;
                    if (ghostPos[len][nx][ny] == -1) {
                        ghostPos[len][nx][ny] = len;
                        queue.add(new int[]{nx, ny, len});
                    }
                }
            }

            // BFS for girl
            int[][] dist = new int[h][w];
            for (int[] row : dist) Arrays.fill(row, -1);
            Queue<int[]> qGirl = new LinkedList<>();
            qGirl.add(new int[]{0, 0});
            dist[0][0] = 0;

            int answerTime = -1, ansX = -1, ansY = -1;

            while (!qGirl.isEmpty()) {
                int[] cur = qGirl.poll();
                int x = cur[0], y = cur[1];
                int t = dist[x][y];

                // check if girl can meet ghost at this time
                int modT = t % (len + 1);
                if (ghostPos[modT][x][y] != -1 && ghostPos[modT][x][y] <= t) {
                    if (answerTime == -1 || t < answerTime) {
                        answerTime = t;
                        ansX = x;
                        ansY = y;
                    }
                }

                if (answerTime != -1 && t >= answerTime) continue;

                for (int d = 0; d < 5; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx >= 0 && nx < h && ny >= 0 && ny < w && grid[nx][ny] == '.') {
                        if (dist[nx][ny] == -1) {
                            dist[nx][ny] = t + 1;
                            qGirl.add(new int[]{nx, ny});
                        }
                    }
                }
            }

            if (answerTime == -1) {
                System.out.println("impossible");
            } else {
                System.out.println(answerTime + " " + ansX + " " + ansY);
            }
        }
        sc.close();
    }
}

