public class Main {
    static final int INF = 1_000_000_000;
    static final int[] DR = {-1, 1, 0, 0, 0};
    static final int[] DC = {0, 0, -1, 1, 0};

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer wObj = fs.nextIntNullable();
            if (wObj == null) break;
            int W = wObj;
            int H = fs.nextInt();
            if (W == 0 && H == 0) break;

            char[][] grid = new char[H][];
            int sr = -1, sc = -1;
            int gr = -1, gc = -1;

            for (int i = 0; i < H; i++) {
                String s = fs.next();
                grid[i] = s.toCharArray();
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == 'A') {
                        sr = i; sc = j;
                        grid[i][j] = '.';
                    } else if (grid[i][j] == 'B') {
                        gr = i; gc = j;
                        grid[i][j] = '.';
                    }
                }
            }

            String pattern = fs.next();
            int L = pattern.length();

            int[][] ghostR = new int[L + 1][1];
            int[][] ghostC = new int[L + 1][1];

            int[] gR = new int[L + 1];
            int[] gC = new int[L + 1];
            gR[0] = gr;
            gC[0] = gc;

            for (int t = 0; t < L; t++) {
                int nr = gR[t], nc = gC[t];
                char ch = pattern.charAt(t);
                if (ch == 'N') nr--;
                else if (ch == 'S') nr++;
                else if (ch == 'W') nc--;
                else if (ch == 'E') nc++;
                gR[t + 1] = nr;
                gC[t + 1] = nc;
            }

            int cells = H * W;
            int[][] dist = new int[cells][L];
            for (int i = 0; i < cells; i++) Arrays.fill(dist[i], INF);

            ArrayDeque<State> q = new ArrayDeque<>();
            int startId = sr * W + sc;
            dist[startId][0] = 0;
            q.add(new State(sr, sc, 0));

            int ansTime = -1, ansR = -1, ansC = -1;

            while (!q.isEmpty()) {
                State cur = q.poll();
                int id = cur.r * W + cur.c;
                int d = dist[id][cur.mod];

                if (cur.r == gR[cur.mod] && cur.c == gC[cur.mod]) {
                    ansTime = d;
                    ansR = cur.r;
                    ansC = cur.c;
                    break;
                }

                for (int mv = 0; mv < 5; mv++) {
                    int nr = cur.r + DR[mv];
                    int nc = cur.c + DC[mv];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    if (grid[nr][nc] != '.') continue;
                    int nmod = (cur.mod + 1) % L;
                    int nid = nr * W + nc;
                    if (dist[nid][nmod] > d + 1) {
                        dist[nid][nmod] = d + 1;
                        q.add(new State(nr, nc, nmod));
                    }
                }
            }

            if (ansTime < 0) {
                out.append("impossible\n");
            } else {
                out.append(ansTime).append(' ')
                   .append(ansC).append(' ')
                   .append(ansR).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static class State {
        int r, c, mod;
        State(int r, int c, int mod) {
            this.r = r;
            this.c = c;
            this.mod = mod;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

