#include <bits/stdc++.h>
using namespace std;

struct State {
    int x, y, p, t;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H;
    while (cin >> W >> H) {
        if (W == 0 && H == 0) break;

        vector<string> g(H);
        for (int i = 0; i < H; ++i) cin >> g[i];

        int gx = -1, gy = -1, sx = -1, sy = -1;
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                if (g[y][x] == 'G') {
                    gx = x; gy = y;
                    g[y][x] = '.';
                } else if (g[y][x] == 'M') {
                    sx = x; sy = y;
                    g[y][x] = '.';
                }
            }
        }

        string pat;
        cin >> pat;
        int L = (int)pat.size();

        // Ghost positions at each time modulo L, and whether it is on a walkable cell for the girl.
        vector<pair<int,int>> ghostPos(L);
        int cx = gx, cy = gy;
        for (int i = 0; i < L; ++i) {
            ghostPos[i] = {cx, cy};
            char c = pat[i];
            int nx = cx, ny = cy;
            if (c == 'N') ny--;
            else if (c == 'S') ny++;
            else if (c == 'W') nx--;
            else if (c == 'E') nx++;
            // Ghost can move through walls/obstacles, but remains inside the map in valid data.
            cx = nx; cy = ny;
        }

        // BFS on (x, y, time mod L)
        vector<vector<vector<int>>> dist(H, vector<vector<int>>(W, vector<int>(L, -1)));
        queue<State> q;

        if (g[sy][sx] == '.') {
            dist[sy][sx][0] = 0;
            q.push({sx, sy, 0, 0});
        }

        const int dx[5] = {0, 0, -1, 1, 0};
        const int dy[5] = {-1, 1, 0, 0, 0};

        int answer = -1;

        while (!q.empty()) {
            State cur = q.front();
            q.pop();

            // If at current time she meets the ghost on a cell she can stand on.
            if (ghostPos[cur.p].first == cur.x && ghostPos[cur.p].second == cur.y && g[cur.y][cur.x] == '.') {
                answer = cur.t;
                break;
            }

            int np = (cur.p + 1) % L;
            for (int dir = 0; dir < 5; ++dir) {
                int nx = cur.x + dx[dir];
                int ny = cur.y + dy[dir];
                if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
                if (g[ny][nx] != '.') continue;
                if (dist[ny][nx][np] != -1) continue;
                dist[ny][nx][np] = cur.t + 1;
                q.push({nx, ny, np, cur.t + 1});
            }
        }

        if (answer == -1) cout << "impossible\n";
        else cout << answer << "\n";
    }

    return 0;
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split('\n')
    idx = 0
    while idx < len(input_data):
        line = input_data[idx].strip(); idx += 1
        if not line: continue
        parts = line.split()
        if len(parts) < 2: continue
        H, W = int(parts[0]), int(parts[1])
        grid = []
        for i in range(H):
            grid.append(input_data[idx]); idx += 1
        pattern = input_data[idx].strip(); idx += 1
        # Find girl 'G' and ghost 'S' (or however they're marked)
        girl = ghost = None
        for r in range(H):
            for c in range(len(grid[r])):
                if grid[r][c] == 'G': girl = (r,c)
                if grid[r][c] == 'S': ghost = (r,c)
        # BFS for girl
        dist = {girl: 0}
        q = deque([girl])
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]
        while q:
            r,c = q.popleft()
            for dr,dc in dirs:
                nr,nc = r+dr,c+dc
                if 0<=nr<H and 0<=nc<len(grid[nr]) and grid[nr][nc]!='#' and (nr,nc) not in dist:
                    dist[(nr,nc)] = dist[(r,c)]+1
                    q.append((nr,nc))
        dmap = {'N':(-1,0),'S':(1,0),'E':(0,1),'W':(0,-1)}
        L = len(pattern)
        MAX_T = L*(H*W+1)+H*W
        MAX_T = min(MAX_T, 100000)
        gr,gc = ghost
        for t in range(MAX_T+1):
            if grid[gr][gc] != '#' and (gr,gc) in dist and dist[(gr,gc)] <= t:
                print(t, gr+1, gc+1); break
            if t < MAX_T:
                cmd = pattern[t % L]
                if cmd in dmap:
                    dr,dc = dmap[cmd]; gr+=dr; gc+=dc
        else:
            print('impossible')

solve()
